pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        address owner = address(this);
        address frozenUser = address(0x123);
        vm.deal(frozenUser, 1 ether);

        c.mintToken(owner, 1000);
        c.mintToken(frozenUser, 500);

        c.burn(200);

        c.freezeAccount(frozenUser, true);

        vm.prank(frozenUser);
        bool ok;
        try c.transfer(owner, 100) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
